INSERT INTO materials (name, category, price, unit, description, image_url, in_stock, sort_order, archived) VALUES ('Кирпич силикатный чёрный пустотелый полуторный М-150', 'kirpich', '27,10 ₽', 'шт', 'Борский силикатный завод. Размер 250×120×88 мм. В упаковке (на поддоне) 336 шт — 9 105,60 ₽. Вес поддона 1340 кг. Чёрный пустотелый — для красивой кладки, лёгкий и тёплый.', '/img/brick-black-card.jpg', true, 6, false);